inline const CNP *GetCNP(const void *buf) {
  return ::flatbuffers::GetRoot<CNP>(buf);
}

inline const CNP *GetSizePrefixedCNP(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<CNP>(buf);
}

inline const char *CNPIdentifier() {
  return "$CNP";
}

inline bool CNPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, CNPIdentifier());
}

inline bool SizePrefixedCNPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, CNPIdentifier(), true);
}

template <bool B = false>
inline bool VerifyCNPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<CNP>(CNPIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedCNPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<CNP>(CNPIdentifier());
}

inline void FinishCNPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<CNP> root) {
  fbb.Finish(root, CNPIdentifier());
}

inline void FinishSizePrefixedCNPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<CNP> root) {
  fbb.FinishSizePrefixed(root, CNPIdentifier());
}

inline std::unique_ptr<CNPT> UnPackCNP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<CNPT>(GetCNP(buf)->UnPack(res));
}

inline std::unique_ptr<CNPT> UnPackSizePrefixedCNP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<CNPT>(GetSizePrefixedCNP(buf)->UnPack(res));
}

